        match ty {
            Type::Named { arguments, .. } => {
                for child in arguments {
                    push(&mut stack, child, reserve)?;
                }
            }
            Type::Function { parameters, result } => {
                for child in parameters {
                    push(&mut stack, child, reserve)?;
                }
                push(&mut stack, result, reserve)?;
            }
            _ => {}
        }
        maximum = maximum.max(stack.len());
    }
    Ok(maximum)
}
